package mm.teashop.api;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import mm.teashop.api.ApiDtos.*; import mm.teashop.domain.*; import mm.teashop.repo.*; import mm.teashop.service.ManagementService; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/manage") @RequiredArgsConstructor public class ManagementController {
 private final IngredientRepository ingredients; private final StockMovementRepository movements; private final WaiterRepository waiters; private final SaleOrderRepository orders; private final ManagementService service;
 @GetMapping("/ingredients") List<Ingredient> ingredients(){return ingredients.findAll();} @PostMapping("/ingredients") Ingredient add(@Valid @RequestBody IngredientRequest r){return service.saveIngredient(null,r);} @PutMapping("/ingredients/{id}") Ingredient edit(@PathVariable Long id,@Valid @RequestBody IngredientRequest r){return service.saveIngredient(id,r);} @DeleteMapping("/ingredients/{id}") void delete(@PathVariable Long id){ingredients.deleteById(id);}
 @PostMapping("/ingredients/{id}/stock") StockMovement stock(@PathVariable Long id,@Valid @RequestBody StockRequest r){return service.stock(id,r);} @GetMapping("/movements") List<StockMovement> movements(@RequestParam LocalDate from,@RequestParam LocalDate to){return movements.findByCreatedAtBetweenOrderByCreatedAtDesc(from.atStartOfDay(),to.plusDays(1).atStartOfDay());} @GetMapping("/expiry") List<Ingredient> expiry(@RequestParam(defaultValue="30") int days){return ingredients.findByExpiryDateBetweenOrderByExpiryDate(LocalDate.now(),LocalDate.now().plusDays(days));}
 @GetMapping("/waiters") List<Waiter> waiters(){return waiters.findAll();} @PostMapping("/waiters") Waiter addWaiter(@Valid @RequestBody WaiterRequest r){return service.saveWaiter(null,r);} @PutMapping("/waiters/{id}") Waiter editWaiter(@PathVariable Long id,@Valid @RequestBody WaiterRequest r){return service.saveWaiter(id,r);} @PostMapping("/waiters/login") Waiter login(@Valid @RequestBody LoginRequest r){return waiters.findByCodeAndPinAndActiveTrue(r.code(),r.pin()).orElseThrow(()->new IllegalArgumentException("Invalid waiter code or PIN"));}
 @GetMapping("/reports") Map<String,Object> report(@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(required=false) Long waiterId){var data=orders.between(from.atStartOfDay(),to.plusDays(1).atStartOfDay()).stream().filter(o->waiterId==null||(o.getWaiter()!=null&&o.getWaiter().getId().equals(waiterId))).toList();var paid=data.stream().filter(o->o.getStatus()==Enums.OrderStatus.PAID).toList();var sales=paid.stream().map(SaleOrder::getTotal).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add);var byWaiter=paid.stream().collect(java.util.stream.Collectors.groupingBy(o->o.getWaiter()==null?"Unassigned":o.getWaiter().getName(),java.util.stream.Collectors.reducing(java.math.BigDecimal.ZERO,SaleOrder::getTotal,java.math.BigDecimal::add)));return Map.of("from",from,"to",to,"orders",data.size(),"paidOrders",paid.size(),"sales",sales,"salesByWaiter",byWaiter);}
}
